def forecast(history: list[float], horizon: int, frequency: str) -> list[float]:
    import math
    import statistics
    x = []
    for v in history:
        try:
            z = float(v)
            if math.isfinite(z):
                x.append(z)
        except (TypeError, ValueError):
            pass
    if horizon <= 0:
        return []
    if not x:
        return [0.0] * horizon
    f = frequency.lower()
    p = 24 if 'hour' in f else (7 if 'day' in f else 1)
    if len(x) < p + 2:
        level = statistics.median(x[-min(7, len(x)):])
        return [float(level)] * horizon

    def smape(a, b):
        return 200.0 * abs(a - b) / (abs(a) + abs(b) + 1e-12)

    def predict(kind, data, origin, k):
        phase = k % p
        cycle = 1 + k // p
        last_idx = origin - p + phase
        last = data[last_idx] if 0 <= last_idx < origin else data[origin - 1]
        if kind == 'last_cycle':
            return last
        if kind == 'phase_median':
            vals = []
            for c in range(3):
                idx = origin - p + phase - c * p
                if 0 <= idx < origin:
                    vals.append(data[idx])
            return statistics.median(vals) if vals else last
        if kind == 'damped_delta':
            deltas = []
            start = max(p, origin - 3 * p)
            for i in range(start, origin):
                deltas.append(data[i] - data[i - p])
            delta = statistics.median(deltas) if deltas else 0.0
            mad = statistics.median([abs(d - delta) for d in deltas]) if deltas else 0.0
            if mad > 0:
                delta = max(-2.5 * mad, min(2.5 * mad, delta))
            return last + 0.35 * cycle * delta
        return statistics.median(data[max(0, origin - min(p, 8)):origin])

    kinds = ['last_cycle', 'phase_median', 'damped_delta', 'recent_level']
    origins = sorted(set(len(x) - j * p for j in range(1, 4) if len(x) - j * p >= p))
    errors = {}
    for kind in kinds:
        fold_errors = []
        for origin in origins:
            width = min(p, len(x) - origin)
            if width <= 0:
                continue
            fold_errors.append(sum(smape(x[origin + k], predict(kind, x, origin, k)) for k in range(width)) / width)
        errors[kind] = sum(fold_errors) / len(fold_errors) if fold_errors else float('inf')
    ranked = sorted(kinds, key=lambda kind: errors[kind])
    selected = [kind for kind in ranked[:2] if math.isfinite(errors[kind])]
    if not selected:
        selected = ['last_cycle']
    weights = [1.0 / max(errors.get(kind, 1.0), 0.05) ** 2 for kind in selected]
    total_weight = sum(weights)
    out = []
    for k in range(horizon):
        value = sum(w * predict(kind, x, len(x), k) for kind, w in zip(selected, weights)) / total_weight
        out.append(float(value if math.isfinite(value) else x[-1]))
    return out
